package com.aoo.bcg.common.repair;import java.time.Instant;import java.util.*;
/** Append-only evidence linking an approved script version and parameters to its immutable outcome. */
public final class ImmutableRepairAudit{public record Record(String operationId,String scriptName,String scriptSha256,String approvalId,String approver,Map<String,String>parameters,String inputHash,String resultHash,String outcome,Instant startedAt,Instant finishedAt){public Record{if(operationId==null||operationId.isBlank()||scriptName==null||scriptName.isBlank()||!sha(scriptSha256)||approvalId==null||approvalId.isBlank()||approver==null||approver.isBlank()||!sha(inputHash)||!sha(resultHash)||outcome==null||outcome.isBlank()||startedAt==null||finishedAt==null||finishedAt.isBefore(startedAt))throw new IllegalArgumentException("invalid immutable repair audit");parameters=Map.copyOf(parameters==null?Map.of():parameters);}private static boolean sha(String value){return value!=null&&value.matches("[0-9a-f]{64}");}}public interface AppendOnlyStore{boolean exists(String operationId);void append(Record record);}public void append(AppendOnlyStore store,Record record){Objects.requireNonNull(store);Objects.requireNonNull(record);if(store.exists(record.operationId()))throw new IllegalStateException("repair audit already immutable");store.append(record);}}
